 if exists(select 1 from public.catalogue_variants t join desired_catalogue_variants e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.card_id is distinct from e.card_id or t.variant_order is distinct from e.variant_order or t.subset is distinct from e.subset or t.card_number is distinct from e.card_number or t.display_name is distinct from e.display_name or t.parallel is distinct from e.parallel or t.serial_cap is distinct from e.serial_cap or t.serial_exact is distinct from e.serial_exact or t.exclusive_note is distinct from e.exclusive_note or t.numbering_note is distinct from e.numbering_note or t.verification_status is distinct from e.verification_status)
 then raise exception 'Conflicting catalogue_variants identity; refusing overwrite'; end if;
end $$;
insert into public.catalogue_variants(id,set_id,card_id,variant_order,subset,card_number,display_name,parallel,serial_cap,serial_exact,exclusive_note,numbering_note,verification_status) select id,set_id,card_id,variant_order,subset,card_number,display_name,parallel,serial_cap,serial_exact,exclusive_note,numbering_note,verification_status from desired_catalogue_variants on conflict do nothing;
create temporary table desired_catalogue_sources on commit drop as select * from jsonb_populate_recordset(null::public.catalogue_sources,'[{"id":"2026-topps-royalty-wwe-checklist","set_id":"2026-topps-royalty-wwe","source":"Topps official checklist","purpose":"Card identities and printed checklist codes","url":"https://cdn.shopify.com/s/files/1/0662/9749/5709/files/26RWWE_-_2026_Topps_Royalty_Collection_WWE_Checklist.xls_-_Read-Only_-_Compatibility_Mode.pdf?v=1795531628","notes":"Official checklist identity only. Parallel applicability and serial caps unverified; Liquid Silver/Gold identities absent from PDF. Release announced for 4 December 2026; shipping unconfirmed."},{"id":"2026-topps-royalty-wwe-release","set_id":"2026-topps-royalty-wwe","source":"Topps UK","purpose":"UK availability via EQL","url":"https://uk.topps.com/pages/topps-royalty-wwe","notes":"Official checklist identity only. Parallel applicability and serial caps unverified; Liquid Silver/Gold identities absent from PDF. Release announced for 4 December 2026; shipping unconfirmed."}]'::jsonb);
do $$ begin
 if exists(select 1 from public.catalogue_sources t join desired_catalogue_sources e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.source is distinct from e.source or t.purpose is distinct from e.purpose or t.url is distinct from e.url or t.notes is distinct from e.notes)
 then raise exception 'Conflicting catalogue_sources identity; refusing overwrite'; end if;
end $$;
insert into public.catalogue_sources(id,set_id,source,purpose,url,notes) select id,set_id,source,purpose,url,notes from desired_catalogue_sources on conflict do nothing;
do $$ begin
 if (select count(*) from public.catalogue_sets where id='2026-topps-royalty-wwe')<>1
 or (select count(*) from public.catalogue_subsets where set_id='2026-topps-royalty-wwe')<>38
 or (select count(*) from public.catalogue_cards where set_id='2026-topps-royalty-wwe')<>878
 or (select count(*) from public.catalogue_variants where set_id='2026-topps-royalty-wwe')<>878
 or (select count(*) from public.catalogue_sources where set_id='2026-topps-royalty-wwe')<>2
 or (select count(*) from public.catalogue_sets)<>50
 or (select count(*) from public.catalogue_cards)<>26175
 or exists(select 1 from public.catalogue_variants v left join public.catalogue_cards c on c.id=v.card_id where v.set_id='2026-topps-royalty-wwe' and (c.id is null or c.set_id<>v.set_id))
 or exists(select 1 from public.catalogue_subsets s where s.set_id='2026-topps-royalty-wwe' and s.card_count<>(select count(*) from public.catalogue_cards c where c.set_id=s.set_id and c.subset_code=s.subset_code))
 or exists(select row from before_catalogue_sets except all select to_jsonb(t) from public.catalogue_sets t)
 or exists(select row from before_catalogue_subsets except all select to_jsonb(t) from public.catalogue_subsets t)
 or exists(select row from before_catalogue_cards except all select to_jsonb(t) from public.catalogue_cards t)
 or exists(select row from before_catalogue_variants except all select to_jsonb(t) from public.catalogue_variants t)
 or exists(select row from before_catalogue_sources except all select to_jsonb(t) from public.catalogue_sources t)
 or exists(select row from before_collection_items except all select to_jsonb(t) from public.collection_items t)
 or exists(select row from before_reference_images except all select to_jsonb(t) from public.reference_images t)
 or exists(select to_jsonb(t) from public.collection_items t except all select row from before_collection_items)
 or exists(select to_jsonb(t) from public.reference_images t except all select row from before_reference_images)
 then raise exception 'Count, linkage or preservation check failed'; end if;
end $$;
select 'verified' as result,(select count(*) from public.catalogue_cards) as cards,(select count(*) from public.collection_items) as collections;
commit;
